package com.citacloud.app.views;

import com.citacloud.app.models.*;
import com.citacloud.app.security.*;
import com.citacloud.app.services.*;
import com.vaadin.flow.component.*;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.combobox.ComboBox;
import com.vaadin.flow.component.grid.Grid;
import com.vaadin.flow.component.html.*;
import com.vaadin.flow.component.icon.VaadinIcon;
import com.vaadin.flow.component.orderedlayout.*;
import com.vaadin.flow.component.tabs.*;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.router.*;
import jakarta.annotation.security.PermitAll;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

@Route(value="historial-clinico",layout=MainLayout.class) @PageTitle("Historial clínico | CitaCloud") @PermitAll
public class HistorialClinicoView extends VerticalLayout {
 private final PacienteService pacientes; private final CitaService citas; private final SignosVitalesService signos; private final ConsultaComplementariaService clinicos; private final RecetaService recetas; private final OrdenEstudioService ordenes; private final DocumentoService documentos; private final UUID empresa;
 private final TextField buscar=new TextField(); private final VerticalLayout contenido=new VerticalLayout(); private Paciente paciente; private Tabs tabs;
 private static final DateTimeFormatter FECHA=DateTimeFormatter.ofPattern("dd/MM/yyyy");
 public HistorialClinicoView(PacienteService p,CitaService c,SignosVitalesService s,ConsultaComplementariaService cl,RecetaService r,OrdenEstudioService o,DocumentoService d){pacientes=p;citas=c;signos=s;clinicos=cl;recetas=r;ordenes=o;documentos=d;TenantUserDetails u=AuthService.getAuthenticatedUser();empresa=u==null?null:u.getEmpresaId();setSizeFull();setPadding(true);getStyle().set("padding-bottom","14rem").set("overflow-y","auto").set("min-height","0");inicio();}
 private void inicio(){removeAll();add(new H2("Historial clínico"),new Paragraph("Consulte la evolución clínica del paciente."));buscar.setLabel("Buscar paciente");buscar.setPlaceholder("Nombre, cédula o teléfono...");buscar.setPrefixComponent(VaadinIcon.SEARCH.create());buscar.setWidthFull();buscar.setClearButtonVisible(true);Grid<Paciente> tabla=new Grid<>(Paciente.class,false);tabla.addColumn(Paciente::getNombreCompleto).setHeader("PACIENTE");tabla.addColumn(Paciente::getDocumento).setHeader("DOCUMENTO");tabla.addColumn(Paciente::getTelefono).setHeader("TELÉFONO");tabla.addColumn(this::edad).setHeader("EDAD");tabla.addComponentColumn(x->new Button("Abrir historial",e->abrir(x))).setHeader("ACCIÓN");tabla.setItems(pacientesFiltrados());Button filtrar=new Button("Buscar",VaadinIcon.SEARCH.create(),e->inicio());HorizontalLayout filtro=new HorizontalLayout(buscar,filtrar);filtro.setWidthFull();filtro.setAlignItems(Alignment.END);add(filtro,tabla(tabla,"No hay pacientes que coincidan con la búsqueda."));}
 private void abrir(Paciente p){paciente=p;removeAll();add(cabecera(),indicadores());buscar.setLabel("Buscar en historial");buscar.setPlaceholder("Diagnóstico, tratamiento, receta, orden...");buscar.setPrefixComponent(VaadinIcon.SEARCH.create());buscar.setClearButtonVisible(true);buscar.addValueChangeListener(e->mostrar());tabs=new Tabs(new Tab("Resumen"),new Tab("Consultas"),new Tab("Signos vitales"),new Tab("Antecedentes"),new Tab("Alergias"),new Tab("Diagnósticos"),new Tab("Tratamientos"),new Tab("Recetas"),new Tab("Órdenes / Estudios"),new Tab("Documentos"));tabs.setWidthFull();tabs.addSelectedChangeListener(e->mostrar());contenido.setPadding(false);contenido.setWidthFull();add(buscar,tabs,contenido);mostrar();}
 private Component cabecera(){List<AlergiaPaciente> alergias=alergias().stream().filter(x->"ACTIVA".equals(x.getEstado())).toList();H2 nombre=new H2(paciente.getNombreCompleto().toUpperCase());nombre.getStyle().set("margin","0");Button cambiar=new Button("Cambiar paciente",e->inicio());HorizontalLayout fila=new HorizontalLayout(nombre,new Span("Expediente: "+v(paciente.getNumeroExpediente())),cambiar);fila.setWidthFull();fila.setJustifyContentMode(JustifyContentMode.BETWEEN);Div datos=new Div(new Text("Cédula: "+v(paciente.getDocumento())+" · "+edad(paciente)+" · "+v(paciente.getGenero())+" · Tel: "+v(paciente.getTelefono())));VerticalLayout caja=new VerticalLayout(fila,datos);caja.setPadding(true);caja.getStyle().set("border","1px solid var(--lumo-contrast-10pct)").set("border-radius","12px");if(!alergias.isEmpty()){Div alerta=new Div(new Text("⚠ ALERGIAS: "+alergias.stream().map(x->x.getAlergeno()+" ("+x.getSeveridad()+")").reduce((a,b)->a+" · "+b).orElse("")));alerta.getStyle().set("background","#fee2e2").set("color","#991b1b").set("font-weight","700").set("padding",".7rem").set("border-radius","8px");caja.add(alerta);}return caja;}
 private Component indicadores(){HorizontalLayout fila=new HorizontalLayout(card("Última consulta",consultas().isEmpty()?"Sin consultas":f(consultas().getFirst().getFecha())),card("Diagnósticos",String.valueOf(diagnosticos().size())),card("Tratamientos",String.valueOf(tratamientos().size())),card("Alergias",String.valueOf(alergias().size())));fila.setWidthFull();fila.getStyle().set("flex-wrap","wrap");return fila;}
 private void mostrar(){contenido.removeAll();if(tabs==null)return;contenido.add(switch(tabs.getSelectedIndex()){case 0->resumen();case 1->consultasTab();case 2->signosTab();case 3->gridAntecedentes();case 4->gridAlergias();case 5->gridDiagnosticos();case 6->gridTratamientos();case 7->gridRecetas();case 8->gridOrdenes();default->gridDocumentos();});}
 private Component resumen(){VerticalLayout x=bloque("Resumen clínico");x.setWidthFull();x.setMaxWidth("1100px");x.setAlignItems(Alignment.CENTER);x.getStyle().set("margin","0 auto").set("box-shadow","var(--lumo-box-shadow-s)");H2 titulo=new H2("Resumen clínico del paciente");titulo.getStyle().set("margin","0");HorizontalLayout superior=new HorizontalLayout(resumenCard("Última consulta",consultas().isEmpty()?"Sin consultas":f(consultas().getFirst().getFecha()),consultas().isEmpty()?"Aún no hay atenciones finalizadas.":consultas().getFirst().getMedico().getNombreCompleto()),resumenCard("Últimos signos vitales",signosPaciente().isEmpty()?"Sin registros":pa(signosPaciente().getFirst()),signosPaciente().isEmpty()?"Aún no hay mediciones.":resumenSignos(signosPaciente().getFirst())));superior.setWidthFull();superior.getStyle().set("flex-wrap","wrap");HorizontalLayout inferiores=new HorizontalLayout(resumenCard("Diagnósticos activos",String.valueOf(diagnosticos().stream().filter(d->"ACTIVO".equals(d.getEstado())||"EN SEGUIMIENTO".equals(d.getEstado())).count()),diagnosticos().stream().filter(d->"ACTIVO".equals(d.getEstado())||"EN SEGUIMIENTO".equals(d.getEstado())).map(this::dx).findFirst().orElse("Sin diagnósticos activos.")),resumenCard("Tratamientos activos",String.valueOf(tratamientos().stream().filter(t->"ACTIVO".equals(t.getEstado())).count()),tratamientos().stream().filter(t->"ACTIVO".equals(t.getEstado())).map(Tratamiento::getDescripcion).findFirst().orElse("Sin tratamientos activos.")));inferiores.setWidthFull();inferiores.getStyle().set("flex-wrap","wrap");x.removeAll();x.add(titulo,superior,inferiores);return x;}
 private Component consultasTab(){Grid<Cita> g=new Grid<>(Cita.class,false);g.addColumn(x->f(x.getFecha())).setHeader("FECHA");g.addColumn(Cita::getHoraInicio).setHeader("HORA");g.addColumn(x->x.getMedico().getEspecialidadesTexto()).setHeader("ESPECIALIDAD");g.addColumn(x->x.getMedico().getNombreCompleto()).setHeader("MÉDICO");g.addColumn(Cita::getMotivo).setHeader("MOTIVO");g.addColumn(x->"FINALIZADA").setHeader("ESTADO");g.setItems(consultas().stream().filter(x->coincide(x.getMotivo(),x.getMedico().getNombreCompleto(),x.getMedico().getEspecialidadesTexto())).toList());return tabla(g,"No hay consultas finalizadas que coincidan con los filtros.");}
 private Component signosTab(){Grid<SignosVitales> g=new Grid<>(SignosVitales.class,false);g.addColumn(x->f(x.getFecha().toLocalDate())).setHeader("FECHA");g.addColumn(this::pa).setHeader("PA");g.addColumn(SignosVitales::getFrecuenciaCardiaca).setHeader("FC");g.addColumn(SignosVitales::getFrecuenciaRespiratoria).setHeader("FR");g.addColumn(SignosVitales::getTemperatura).setHeader("TEMP.");g.addColumn(x->v(x.getSaturacionOxigeno())+"%").setHeader("SpO₂");g.addColumn(SignosVitales::getPeso).setHeader("PESO");g.addColumn(SignosVitales::getImc).setHeader("IMC");g.setItems(signosPaciente());return tabla(g,"No hay signos vitales registrados para este paciente.");}
 private Component gridAntecedentes(){Grid<AntecedenteMedico> g=new Grid<>(AntecedenteMedico.class,false);g.addColumn(AntecedenteMedico::getTipo).setHeader("TIPO");g.addColumn(AntecedenteMedico::getDescripcion).setHeader("DESCRIPCIÓN");g.addColumn(AntecedenteMedico::getEstado).setHeader("ESTADO");g.addColumn(x->f(x.getFechaAproximada())).setHeader("FECHA");g.addColumn(AntecedenteMedico::getObservaciones).setHeader("OBSERVACIONES");g.setItems(antecedentes().stream().filter(x->coincide(x.getTipo(),x.getDescripcion(),x.getEstado())).toList());return tabla(g,"No hay antecedentes registrados para este paciente.");}
 private Component gridAlergias(){Grid<AlergiaPaciente> g=new Grid<>(AlergiaPaciente.class,false);g.addColumn(AlergiaPaciente::getAlergeno).setHeader("ALÉRGENO");g.addColumn(AlergiaPaciente::getTipo).setHeader("TIPO");g.addColumn(AlergiaPaciente::getReaccion).setHeader("REACCIÓN");g.addColumn(AlergiaPaciente::getSeveridad).setHeader("SEVERIDAD");g.addColumn(AlergiaPaciente::getEstado).setHeader("ESTADO");g.setItems(alergias().stream().filter(x->coincide(x.getAlergeno(),x.getTipo(),x.getEstado())).toList());return tabla(g,"No se ha registrado información sobre alergias.");}
 private Component gridDiagnosticos(){Grid<Diagnostico> g=new Grid<>(Diagnostico.class,false);g.addColumn(Diagnostico::getCodigo).setHeader("CÓDIGO CIE-10");g.addColumn(Diagnostico::getDescripcion).setHeader("DIAGNÓSTICO");g.addColumn(Diagnostico::getEstado).setHeader("ESTADO");g.addColumn(x->f(x.getFechaDiagnostico())).setHeader("PRIMERA APARICIÓN");g.setItems(diagnosticos().stream().filter(x->coincide(x.getCodigo(),x.getDescripcion(),x.getEstado())).toList());return tabla(g,"No hay diagnósticos registrados para este paciente.");}
 private Component gridTratamientos(){Grid<Tratamiento> g=new Grid<>(Tratamiento.class,false);g.addColumn(Tratamiento::getDescripcion).setHeader("TRATAMIENTO");g.addColumn(Tratamiento::getTipo).setHeader("TIPO");g.addColumn(x->f(x.getFechaInicio())).setHeader("INICIO");g.addColumn(x->f(x.getFechaFin())).setHeader("FIN");g.addColumn(Tratamiento::getEstado).setHeader("ESTADO");g.addColumn(Tratamiento::getIndicaciones).setHeader("INDICACIONES");g.setItems(tratamientos().stream().filter(x->coincide(x.getDescripcion(),x.getTipo(),x.getEstado())).toList());return tabla(g,"No hay tratamientos registrados para este paciente.");}
 private Component gridRecetas(){Grid<Receta> g=new Grid<>(Receta.class,false);g.addColumn(Receta::getNumero).setHeader("RECETA");g.addColumn(x->f((x.getEmitidoEn()==null?x.getCreadoEn():x.getEmitidoEn()).toLocalDate())).setHeader("FECHA");g.addColumn(Receta::getEstado).setHeader("ESTADO");g.addColumn(x->recetas.medicamentos(x.getId()).stream().map(DetalleReceta::getMedicamento).reduce((a,b)->a+", "+b).orElse("—")).setHeader("MEDICAMENTOS");g.setItems(recetas.listar(empresa,paciente.getId()).stream().filter(x->coincide(x.getNumero(),x.getEstado())).toList());return tabla(g,"No hay recetas registradas para este paciente.");}
 private Component gridOrdenes(){Grid<OrdenEstudio> g=new Grid<>(OrdenEstudio.class,false);g.addColumn(OrdenEstudio::getNumero).setHeader("ORDEN");g.addColumn(OrdenEstudio::getPrioridad).setHeader("PRIORIDAD");g.addColumn(OrdenEstudio::getEstado).setHeader("ESTADO");g.addColumn(x->ordenes.estudios(x.getId()).stream().map(DetalleOrdenEstudio::getEstudio).reduce((a,b)->a+", "+b).orElse("—")).setHeader("ESTUDIOS");g.setItems(ordenes.listar(empresa,paciente.getId()).stream().filter(x->coincide(x.getNumero(),x.getEstado())).toList());return tabla(g,"No hay órdenes o estudios registrados para este paciente.");}
 private Component gridDocumentos(){Grid<Documento> g=new Grid<>(Documento.class,false);g.addColumn(x->(x.getTipo()!=null&&x.getTipo().startsWith("image/")?"🖼 ":"📄 ")+x.getNombre()).setHeader("NOMBRE");g.addColumn(x->"application/pdf".equals(x.getTipo())?"Documento PDF":x.getTipo()!=null&&x.getTipo().startsWith("image/")?"Imagen clínica":"Otro").setHeader("TIPO");g.addColumn(x->x.getFecha()==null?"—":x.getFecha().toLocalDate().format(FECHA)).setHeader("FECHA");g.addColumn(x->x.getDescripcion()==null||x.getDescripcion().isBlank()?"Manual":"Carga manual").setHeader("ORIGEN");g.addComponentColumn(x->{Button ver=new Button(VaadinIcon.EYE.create(),e->getUI().ifPresent(ui->ui.getPage().open("documentos/"+x.getId()+"/ver","_blank")));ver.setTooltipText("Ver documento");Button descargar=new Button(VaadinIcon.DOWNLOAD.create(),e->getUI().ifPresent(ui->ui.getPage().open("documentos/"+x.getId(),"_blank")));descargar.setTooltipText("Descargar");return new HorizontalLayout(ver,descargar);}).setHeader("ACCIONES");g.setItems(documentosPaciente().stream().filter(x->coincide(x.getNombre(),x.getDescripcion(),x.getNombreArchivo())).toList());return tabla(g,"Este paciente todavía no tiene documentos.");}
 private List<Paciente> pacientesFiltrados(){String q=buscar.getValue().toLowerCase();return empresa==null?List.of():pacientes.listarPorEmpresa(empresa).stream().filter(x->q.isBlank()||(x.getNombreCompleto()+" "+v(x.getDocumento())+" "+v(x.getTelefono())).toLowerCase().contains(q)).toList();}
 private List<Cita> consultas(){return empresa==null||paciente==null?List.of():citas.listarPorEmpresa(empresa).stream().filter(x->paciente.getId().equals(x.getPaciente().getId())&&"ATENDIDA".equals(x.getEstado())).sorted(Comparator.comparing(Cita::getFecha).reversed()).toList();} private List<SignosVitales> signosPaciente(){return signos.listarPorPaciente(empresa,paciente.getId());} private List<AntecedenteMedico> antecedentes(){return clinicos.listarAntecedentes(empresa,paciente.getId());} private List<AlergiaPaciente> alergias(){return clinicos.listarAlergias(empresa,paciente.getId());} private List<Diagnostico> diagnosticos(){return clinicos.listarDiagnosticos(empresa,paciente.getId());} private List<Tratamiento> tratamientos(){return clinicos.listarTratamientos(empresa,paciente.getId());}
 private List<Documento> documentosPaciente(){return empresa==null||paciente==null?List.of():documentos.listar(empresa).stream().filter(x->x.getPaciente()!=null&&paciente.getId().equals(x.getPaciente().getId())&&"ACTIVO".equals(x.getEstado())).toList();}
 private boolean coincide(String... valores){String q=buscar.getValue().trim().toLowerCase();return q.isBlank()||Arrays.stream(valores).filter(Objects::nonNull).anyMatch(x->x.toLowerCase().contains(q));} @SuppressWarnings({"rawtypes","unchecked"}) private Component tabla(Grid<?> g,String mensaje){List datos=g.getListDataView().getItems().toList();if(datos.isEmpty())return vacio(mensaje);final int[] porPagina={10},pagina={0};Span estado=new Span();ComboBox<Integer> filas=new ComboBox<>("Filas por página",List.of(10,25,50));filas.setValue(10);filas.setWidth("150px");Button anterior=new Button("Anterior");Button siguiente=new Button("Siguiente");Grid cruda=g;Runnable cargar=()->{int total=(datos.size()+porPagina[0]-1)/porPagina[0];if(pagina[0]>=total)pagina[0]=total-1;int inicio=pagina[0]*porPagina[0];cruda.setItems(datos.subList(inicio,Math.min(inicio+porPagina[0],datos.size())));g.setAllRowsVisible(true);g.getStyle().set("height","auto").set("max-height","none");estado.setText("Página "+(pagina[0]+1)+" de "+total+" · "+datos.size()+" registros");anterior.setEnabled(pagina[0]>0);siguiente.setEnabled(pagina[0]<total-1);};filas.addValueChangeListener(e->{porPagina[0]=e.getValue();pagina[0]=0;cargar.run();});anterior.addClickListener(e->{pagina[0]--;cargar.run();});siguiente.addClickListener(e->{pagina[0]++;cargar.run();});cargar.run();HorizontalLayout controles=new HorizontalLayout(filas,anterior,estado,siguiente);controles.setWidthFull();controles.setAlignItems(Alignment.END);controles.setJustifyContentMode(JustifyContentMode.CENTER);VerticalLayout resultado=new VerticalLayout(g,controles);resultado.setPadding(false);resultado.setSpacing(true);resultado.setWidthFull();resultado.getStyle().set("padding-bottom","6rem");return resultado;} private Component resumenCard(String titulo,String valor,String detalle){VerticalLayout c=new VerticalLayout(new Span(titulo),new H2(valor),new Span(detalle));c.setPadding(true);c.setSpacing(false);c.setWidthFull();c.getStyle().set("min-width","260px").set("flex","1").set("background","var(--lumo-contrast-5pct)").set("border-radius","12px").set("border","1px solid var(--lumo-contrast-10pct)");return c;} private Component card(String t,String n){VerticalLayout c=new VerticalLayout(new Span(t),new H3(n));c.setPadding(true);c.setSpacing(false);c.getStyle().set("min-width","150px").set("flex","1").set("border","1px solid var(--lumo-contrast-10pct)").set("border-radius","10px");return c;} private VerticalLayout bloque(String titulo){VerticalLayout x=new VerticalLayout(new H3(titulo));x.setPadding(true);x.getStyle().set("border","1px solid var(--lumo-contrast-10pct)").set("border-radius","12px");return x;} private Component lista(List<String> x,String m){return x.isEmpty()?vacio(m):new UnorderedList(x.stream().map(ListItem::new).toArray(ListItem[]::new));} private Component vacio(String t){Span x=new Span(t);x.getStyle().set("color","var(--lumo-secondary-text-color)").set("font-style","italic");return x;} private String dx(Diagnostico x){return (x.getCodigo()==null?"":x.getCodigo()+" — ")+x.getDescripcion();} private String edad(Paciente x){return x.getFechaNacimiento()==null?"Edad no registrada":Period.between(x.getFechaNacimiento(),LocalDate.now()).getYears()+" años";} private String pa(SignosVitales x){return v(x.getPresionSistolica())+"/"+v(x.getPresionDiastolica());} private String resumenSignos(SignosVitales x){return f(x.getFecha().toLocalDate())+" · PA "+pa(x)+" · FC "+v(x.getFrecuenciaCardiaca())+" · SpO₂ "+v(x.getSaturacionOxigeno())+"% · Peso "+v(x.getPeso())+" kg · IMC "+v(x.getImc());} private String f(LocalDate x){return x==null?"—":FECHA.format(x);} private String v(Object x){return x==null||x.toString().isBlank()?"—":x.toString();}
}
